{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv')
for c in x.columns[2:-1]:
 d=x[[c,'recovery_score','hospital']].dropna(); m=smf.ols(f'recovery_score ~ Q("{c}") + C(hospital)',d).fit()
 print(c, round(m.params.iloc[1],3), round(m.pvalues.iloc[1],5), round(m.rsquared,3))
"}
